CREATE OR REPLACE FUNCTION public.create_order_transactional(p_order_id text, p_order_number text, p_customer_name text, p_customer_email text, p_customer_phone text, p_shipping_address text, p_shipping_city text, p_shipping_province text, p_shipping_postal_code text, p_shipping_notes text, p_payment_method text, p_receipt_path text, p_idempotency_key text, p_request_fingerprint text, p_tracking_token_hash text, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_existing_order record;
  v_payment_status text;
  v_order_status text;
  v_free_thresh integer;
  v_delivery_fee integer;
  v_subtotal integer := 0;
  v_shipping integer := 0;
  v_total integer := 0;
  v_item record;
  r_var record;
  v_item_id text;
  v_line_total integer;
BEGIN
  -- 1. Idempotency Check
  IF p_idempotency_key IS NOT NULL AND TRIM(p_idempotency_key) != '' THEN
    SELECT id, order_number, subtotal_minor, shipping_minor, total_minor, payment_status, order_status, request_fingerprint
    INTO v_existing_order
    FROM public.orders
    WHERE idempotency_key = p_idempotency_key;

    IF FOUND THEN
      IF v_existing_order.request_fingerprint IS NOT NULL AND p_request_fingerprint IS NOT NULL AND v_existing_order.request_fingerprint != p_request_fingerprint THEN
        RAISE EXCEPTION 'Idempotency conflict: key reused with different request fingerprint'
          USING ERRCODE = 'P0001';
      ELSE
        RETURN jsonb_build_object(
          'order_id', v_existing_order.id,
          'order_number', v_existing_order.order_number,
          'subtotal_minor', v_existing_order.subtotal_minor,
          'shipping_minor', v_existing_order.shipping_minor,
          'total_minor', v_existing_order.total_minor,
          'payment_status', v_existing_order.payment_status,
          'order_status', v_existing_order.order_status,
          'is_idempotent_replay', true
        );
      END IF;
    END IF;
  END IF;

  -- 2. Validate Items
  IF p_items IS NULL OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'Order items cannot be empty' USING ERRCODE = 'P0005';
  END IF;

  -- 3. Lock affected product variants in consistent order (ASC) to prevent deadlocks
  -- Calculate demands
  FOR r_var IN (
    WITH raw_items AS (
      SELECT
        (elem->>'product_id') as product_id,
        (elem->>'variant_id') as variant_id,
        (elem->>'kit_id') as kit_id,
        (elem->>'quantity')::int as quantity
      FROM jsonb_array_elements(p_items) elem
    ),
    direct_demand AS (
      SELECT variant_id, SUM(quantity)::int as qty
      FROM raw_items
      WHERE kit_id IS NULL AND variant_id IS NOT NULL
      GROUP BY variant_id
    ),
    kit_demand AS (
      SELECT
        COALESCE(ki.variant_id, ki.product_variant_id) as variant_id,
        SUM(ri.quantity * ki.quantity)::int as qty
      FROM raw_items ri
      JOIN public.kit_items ki ON ki.kit_id = ri.kit_id
      WHERE ri.kit_id IS NOT NULL
      GROUP BY COALESCE(ki.variant_id, ki.product_variant_id)
    ),
    combined_demand AS (
      SELECT variant_id, SUM(qty)::int as total_qty
      FROM (
        SELECT * FROM direct_demand
        UNION ALL
        SELECT * FROM kit_demand
      ) c
      WHERE variant_id IS NOT NULL
      GROUP BY variant_id
    )
    SELECT
      pv.id as variant_id,
      pv.inventory_quantity,
      pv.status as variant_status,
      cd.total_qty,
      p.name as product_name,
      pv.option_value
    FROM public.product_variants pv
    JOIN combined_demand cd ON cd.variant_id = pv.id
    JOIN public.products p ON p.id = pv.product_id
    ORDER BY pv.id ASC
    FOR UPDATE OF pv
  ) LOOP
    IF r_var.variant_status != 'ACTIVE' THEN
      RAISE EXCEPTION 'Product variant "% (%)" is not active', r_var.product_name, r_var.option_value
        USING ERRCODE = 'P0003';
    END IF;

    IF r_var.inventory_quantity < r_var.total_qty THEN
      RAISE EXCEPTION 'Insufficient stock for "% (%)". Available: %, Requested: %',
        r_var.product_name, r_var.option_value, r_var.inventory_quantity, r_var.total_qty
        USING ERRCODE = 'P0002';
    END IF;
  END LOOP;

  -- 4. Decrement inventory for locked variants
  WITH raw_items AS (
    SELECT
      (elem->>'product_id') as product_id,
      (elem->>'variant_id') as variant_id,
      (elem->>'kit_id') as kit_id,
      (elem->>'quantity')::int as quantity
    FROM jsonb_array_elements(p_items) elem
  ),
  direct_demand AS (
    SELECT variant_id, SUM(quantity)::int as qty
    FROM raw_items
    WHERE kit_id IS NULL AND variant_id IS NOT NULL
    GROUP BY variant_id
  ),
  kit_demand AS (
    SELECT
      COALESCE(ki.variant_id, ki.product_variant_id) as variant_id,
      SUM(ri.quantity * ki.quantity)::int as qty
    FROM raw_items ri
    JOIN public.kit_items ki ON ki.kit_id = ri.kit_id
    WHERE ri.kit_id IS NOT NULL
    GROUP BY COALESCE(ki.variant_id, ki.product_variant_id)
  ),
  combined_demand AS (
    SELECT variant_id, SUM(qty)::int as total_qty
    FROM (
      SELECT * FROM direct_demand
      UNION ALL
      SELECT * FROM kit_demand
    ) c
    WHERE variant_id IS NOT NULL
    GROUP BY variant_id
  )
  UPDATE public.product_variants pv
  SET inventory_quantity = pv.inventory_quantity - cd.total_qty,
      updated_at = NOW()
  FROM combined_demand cd
  WHERE pv.id = cd.variant_id;

  -- 5. Calculate Subtotal from authoritative catalog prices
  FOR v_item IN (
    SELECT
      (elem->>'product_id') as product_id,
      (elem->>'variant_id') as variant_id,
      (elem->>'kit_id') as kit_id,
      (elem->>'quantity')::int as quantity
    FROM jsonb_array_elements(p_items) elem
  ) LOOP
    IF v_item.kit_id IS NOT NULL THEN
      SELECT price_minor INTO v_line_total
      FROM public.kits
      WHERE id = v_item.kit_id AND status = 'ACTIVE';

      IF NOT FOUND THEN
        RAISE EXCEPTION 'Kit % is not active or does not exist', v_item.kit_id USING ERRCODE = 'P0003';
      END IF;
      v_subtotal := v_subtotal + (v_line_total * v_item.quantity);
    ELSIF v_item.variant_id IS NOT NULL THEN
      SELECT price_minor INTO v_line_total
      FROM public.product_variants
      WHERE id = v_item.variant_id AND status = 'ACTIVE';

      IF NOT FOUND THEN
        RAISE EXCEPTION 'Variant % is not active or does not exist', v_item.variant_id USING ERRCODE = 'P0003';
      END IF;
      v_subtotal := v_subtotal + (v_line_total * v_item.quantity);
    ELSE
      SELECT price_minor INTO v_line_total
      FROM public.products
      WHERE id = v_item.product_id AND status = 'ACTIVE';

      IF NOT FOUND THEN
        RAISE EXCEPTION 'Product % is not active or does not exist', v_item.product_id USING ERRCODE = 'P0003';
      END IF;
      v_subtotal := v_subtotal + (v_line_total * v_item.quantity);
    END IF;
  END LOOP;

  -- 6. Shipping & Total Calculation
  SELECT COALESCE((SELECT value::int FROM public.site_settings WHERE key = 'free_delivery_threshold_minor'), 200000) INTO v_free_thresh;
  SELECT COALESCE((SELECT value::int FROM public.site_settings WHERE key = 'delivery_fee_minor'), 20000) INTO v_delivery_fee;

  IF v_subtotal >= v_free_thresh THEN
    v_shipping := 0;
  ELSE
    v_shipping := v_delivery_fee;
  END IF;

  v_total := v_subtotal + v_shipping;

  -- 7. Determine initial order and payment status
  IF p_payment_method = 'COD' THEN
    v_payment_status := 'PENDING';
    v_order_status := 'RECEIVED';
  ELSIF p_payment_method = 'wallet_aggregator' OR (p_receipt_path IS NOT NULL AND TRIM(p_receipt_path) != '') THEN
    v_payment_status := 'UNDER_REVIEW';
    v_order_status := 'PAYMENT_REVIEW';
  ELSE
    v_payment_status := 'PENDING';
    v_order_status := 'PENDING_PAYMENT';
  END IF;

  -- 8. Insert Order
  INSERT INTO public.orders (
    id, order_number, customer_name, customer_email, customer_phone,
    shipping_address, shipping_city, shipping_province, shipping_postal_code,
    shipping_notes, currency, subtotal_minor, shipping_minor, discount_minor,
    total_minor, payment_method, payment_status, order_status,
    receipt_path, idempotency_key, request_fingerprint, tracking_token_hash,
    created_at, updated_at
  ) VALUES (
    p_order_id, p_order_number, p_customer_name, p_customer_email, p_customer_phone,
    p_shipping_address, p_shipping_city, p_shipping_province, p_shipping_postal_code,
    p_shipping_notes, 'PKR', v_subtotal, v_shipping, 0,
    v_total, p_payment_method, v_payment_status, v_order_status,
    p_receipt_path, p_idempotency_key, p_request_fingerprint, p_tracking_token_hash,
    NOW(), NOW()
  );

  -- 9. Insert Line Items
  FOR v_item IN (
    SELECT
      elem->>'id' as item_id,
      elem->>'product_id' as product_id,
      elem->>'variant_id' as variant_id,
      elem->>'kit_id' as kit_id,
      (elem->>'quantity')::int as quantity,
      elem->>'name' as client_name,
      elem->>'sku' as client_sku,
      elem->>'image_url' as client_image
    FROM jsonb_array_elements(p_items) elem
  ) LOOP
    v_item_id := COALESCE(v_item.item_id, 'oi-' || extract(epoch from clock_timestamp())::bigint || '-' || floor(random() * 1000)::int);

    IF v_item.kit_id IS NOT NULL THEN
      DECLARE
        k_rec record;
      BEGIN
        SELECT name, price_minor, image_url INTO k_rec FROM public.kits WHERE id = v_item.kit_id;
        INSERT INTO public.order_items (
          id, order_id, product_id, kit_id, variant_id,
          product_name, variant_name, price_minor, quantity, line_total_minor,
          name_snapshot, sku_snapshot, image_url, unit_price_minor,
          created_at, updated_at
        ) VALUES (
          v_item_id, p_order_id, NULL, v_item.kit_id, NULL,
          k_rec.name, NULL, k_rec.price_minor, v_item.quantity, k_rec.price_minor * v_item.quantity,
          k_rec.name, COALESCE(v_item.client_sku, 'KIT-' || v_item.kit_id), COALESCE(k_rec.image_url, v_item.client_image), k_rec.price_minor,
          NOW(), NOW()
        );
      END;
    ELSE
      DECLARE
        p_rec record;
        var_rec record;
        v_name text;
        v_var_name text := NULL;
        v_price int;
        v_sku text;
        v_img text;
      BEGIN
        SELECT name, price_minor, sku, image_url INTO p_rec FROM public.products WHERE id = v_item.product_id;
        v_name := p_rec.name;
        v_price := p_rec.price_minor;
        v_sku := p_rec.sku;
        v_img := p_rec.image_url;

        IF v_item.variant_id IS NOT NULL THEN
          SELECT option_value, price_minor, sku INTO var_rec FROM public.product_variants WHERE id = v_item.variant_id;
          v_var_name := var_rec.option_value;
          v_price := var_rec.price_minor;
          v_sku := var_rec.sku;
          v_name := p_rec.name || ' (' || var_rec.option_value || ')';
        END IF;

        INSERT INTO public.order_items (
          id, order_id, product_id, kit_id, variant_id,
          product_name, variant_name, price_minor, quantity, line_total_minor,
          name_snapshot, sku_snapshot, image_url, unit_price_minor,
          created_at, updated_at
        ) VALUES (
          v_item_id, p_order_id, v_item.product_id, NULL, v_item.variant_id,
          p_rec.name, v_var_name, v_price, v_item.quantity, v_price * v_item.quantity,
          v_name, COALESCE(v_sku, v_item.client_sku), COALESCE(v_img, v_item.client_image), v_price,
          NOW(), NOW()
        );
      END;
    END IF;
  END LOOP;

  -- 10. Audit event
  INSERT INTO public.order_events (
    id, order_id, actor_type, actor_id, event_type, old_status, new_status, metadata, created_at
  ) VALUES (
    gen_random_uuid(), p_order_id, 'CUSTOMER', NULL, 'ORDER_CREATED', NULL, v_order_status,
    jsonb_build_object('payment_status', v_payment_status, 'payment_method', p_payment_method),
    NOW()
  );

  RETURN jsonb_build_object(
    'order_id', p_order_id,
    'order_number', p_order_number,
    'subtotal_minor', v_subtotal,
    'shipping_minor', v_shipping,
    'total_minor', v_total,
    'payment_status', v_payment_status,
    'order_status', v_order_status,
    'is_idempotent_replay', false
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.lookup_order_with_capability(p_order_number text, p_token text DEFAULT NULL::text, p_verify text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_order record;
  v_items jsonb;
  v_is_authorized boolean := false;
  v_token_hash text;
  v_clean_verify text;
  v_clean_phone text;
BEGIN
  SELECT * INTO v_order FROM public.orders WHERE order_number = p_order_number LIMIT 1;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  -- 1. Check if caller is admin
  IF is_admin() THEN
    v_is_authorized := true;
  END IF;

  -- 2. Check capability token
  IF NOT v_is_authorized AND p_token IS NOT NULL AND length(trim(p_token)) > 0 THEN
    v_token_hash := encode(digest(trim(p_token), 'sha256'), 'hex');
    IF v_order.tracking_token_hash IS NOT NULL AND v_order.tracking_token_hash = v_token_hash THEN
      v_is_authorized := true;
    END IF;
  END IF;

  -- 3. Check customer verification (email or phone)
  IF NOT v_is_authorized AND p_verify IS NOT NULL AND length(trim(p_verify)) >= 4 THEN
    v_clean_verify := regexp_replace(lower(trim(p_verify)), '[\s\-\(\)]', '', 'g');
    v_clean_phone := regexp_replace(lower(coalesce(v_order.customer_phone, '')), '[\s\-\(\)]', '', 'g');

    IF lower(trim(p_verify)) = lower(coalesce(v_order.customer_email, '')) THEN
      v_is_authorized := true;
    ELSIF length(v_clean_verify) >= 7 AND (v_clean_phone LIKE '%' || v_clean_verify OR v_clean_verify LIKE '%' || v_clean_phone) THEN
      v_is_authorized := true;
    END IF;
  END IF;

  -- Fetch line items
  SELECT coalesce(jsonb_agg(to_jsonb(it)), '[]'::jsonb) INTO v_items
  FROM public.order_items it
  WHERE it.order_id = v_order.id;

  -- Return either authorized (full) or unauthenticated (masked) projection
  IF v_is_authorized THEN
    RETURN jsonb_build_object(
      'is_authorized', true,
      'order', to_jsonb(v_order),
      'items', v_items
    );
  ELSE
    RETURN jsonb_build_object(
      'is_authorized', false,
      'order', jsonb_build_object(
        'id', v_order.id,
        'order_number', v_order.order_number,
        'order_status', v_order.order_status,
        'payment_status', v_order.payment_status,
        'payment_method', v_order.payment_method,
        'created_at', v_order.created_at,
        'updated_at', v_order.updated_at,
        'subtotal_minor', v_order.subtotal_minor,
        'shipping_minor', v_order.shipping_minor,
        'discount_minor', v_order.discount_minor,
        'total_minor', v_order.total_minor,
        'currency', v_order.currency,
        'shipping_city', v_order.shipping_city,
        'shipping_province', v_order.shipping_province,
        'tracking_courier', v_order.tracking_courier,
        'tracking_number', v_order.tracking_number,
        'customer_name', substring(v_order.customer_name from 1 for 1) || '***',
        'customer_email', CASE WHEN v_order.customer_email IS NOT NULL AND position('@' in v_order.customer_email) > 1 
                               THEN substring(v_order.customer_email from 1 for 1) || '***@' || split_part(v_order.customer_email, '@', 2)
                               ELSE '***' END,
        'customer_phone', CASE WHEN v_order.customer_phone IS NOT NULL AND length(v_order.customer_phone) > 4
                               THEN substring(v_order.customer_phone from 1 for 4) || '****' || right(v_order.customer_phone, 2)
                               ELSE '***' END,
        'shipping_address', 'Hidden for privacy',
        'receipt_path', NULL,
        'admin_note', NULL
      ),
      'items', v_items
    );
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_order_fulfillment_transactional(p_order_id text, p_order_status text, p_tracking_number text DEFAULT NULL::text, p_courier_name text DEFAULT NULL::text, p_actor_type text DEFAULT 'ADMIN'::text, p_actor_id text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_order record;
  v_old_order_status text;
  item_rec record;
  comp_rec record;
BEGIN
  -- Strict Admin Authorization Check
  IF auth.role() IS NOT NULL AND auth.role() != 'service_role' AND NOT public.is_admin() THEN
    RAISE EXCEPTION 'Unauthorized: administrator access required' USING ERRCODE = '42501';
  END IF;

  -- Lock order
  SELECT * INTO v_order
  FROM public.orders
  WHERE id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order % not found', p_order_id USING ERRCODE = 'P0002';
  END IF;

  v_old_order_status := v_order.order_status;

  -- Validate state machine rules
  IF p_order_status IN ('PAID', 'PROCESSING', 'PACKED', 'SHIPPED', 'DELIVERED') THEN
    IF v_order.payment_method != 'COD' AND v_order.payment_status != 'VERIFIED' THEN
      RAISE EXCEPTION 'Verify the payment before updating fulfillment' USING ERRCODE = 'P0004';
    END IF;
  END IF;

  -- Handle cancellation stock restore if cancelled before shipment
  IF p_order_status = 'CANCELLED' AND v_old_order_status NOT IN ('SHIPPED', 'DELIVERED', 'CANCELLED', 'REFUNDED') THEN
    FOR item_rec IN (SELECT * FROM public.order_items WHERE order_id = p_order_id) LOOP
      IF item_rec.variant_id IS NOT NULL THEN
        UPDATE public.product_variants
        SET inventory_quantity = inventory_quantity + item_rec.quantity,
            updated_at = NOW()
        WHERE id = item_rec.variant_id;
      ELSIF item_rec.kit_id IS NOT NULL THEN
        FOR comp_rec IN (SELECT * FROM public.kit_items WHERE kit_id = item_rec.kit_id) LOOP
          IF comp_rec.variant_id IS NOT NULL OR comp_rec.product_variant_id IS NOT NULL THEN
            UPDATE public.product_variants
            SET inventory_quantity = inventory_quantity + (comp_rec.quantity * item_rec.quantity),
                updated_at = NOW()
            WHERE id = COALESCE(comp_rec.variant_id, comp_rec.product_variant_id);
          END IF;
        END LOOP;
      END IF;
    END LOOP;
  END IF;

  UPDATE public.orders
  SET order_status = p_order_status,
      tracking_number = COALESCE(p_tracking_number, tracking_number),
      courier_name = COALESCE(p_courier_name, courier_name),
      tracking_courier = COALESCE(p_courier_name, tracking_courier),
      admin_note = COALESCE(p_notes, admin_note),
      notes = COALESCE(p_notes, notes),
      updated_at = NOW()
  WHERE id = p_order_id;

  INSERT INTO public.order_events (
    id, order_id, actor_type, actor_id, event_type, old_status, new_status, metadata, created_at
  ) VALUES (
    gen_random_uuid(), p_order_id, p_actor_type, p_actor_id, 'ORDER_STATUS_UPDATED',
    v_old_order_status, p_order_status,
    jsonb_build_object('courier_name', p_courier_name, 'tracking_number', p_tracking_number, 'notes', p_notes),
    NOW()
  );

  RETURN jsonb_build_object(
    'order_id', p_order_id,
    'order_status', p_order_status,
    'tracking_number', COALESCE(p_tracking_number, v_order.tracking_number),
    'courier_name', COALESCE(p_courier_name, v_order.courier_name)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.update_order_payment_transactional(p_order_id text, p_payment_status text, p_order_status text DEFAULT NULL::text, p_actor_type text DEFAULT 'ADMIN'::text, p_actor_id text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_order record;
  v_old_payment_status text;
  v_old_order_status text;
  v_new_order_status text;
  item_rec record;
  comp_rec record;
BEGIN
  -- Strict Admin Authorization Check
  IF auth.role() IS NOT NULL AND auth.role() != 'service_role' AND NOT public.is_admin() THEN
    RAISE EXCEPTION 'Unauthorized: administrator access required' USING ERRCODE = '42501';
  END IF;

  -- Lock order
  SELECT * INTO v_order
  FROM public.orders
  WHERE id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order % not found', p_order_id USING ERRCODE = 'P0002';
  END IF;

  v_old_payment_status := v_order.payment_status;
  v_old_order_status := v_order.order_status;
  v_new_order_status := COALESCE(p_order_status, v_old_order_status);

  -- Payment verification logic
  IF p_payment_status = 'VERIFIED' THEN
    IF v_old_order_status IN ('PENDING_PAYMENT', 'PAYMENT_REVIEW', 'RECEIVED') THEN
      v_new_order_status := 'PAID';
    END IF;
  ELSIF p_payment_status = 'REJECTED' OR p_order_status = 'CANCELLED' THEN
    -- If releasing reservation before shipment, restore stock
    IF v_old_order_status NOT IN ('SHIPPED', 'DELIVERED', 'CANCELLED', 'REFUNDED') THEN
      FOR item_rec IN (SELECT * FROM public.order_items WHERE order_id = p_order_id) LOOP
        IF item_rec.variant_id IS NOT NULL THEN
          UPDATE public.product_variants
          SET inventory_quantity = inventory_quantity + item_rec.quantity,
              updated_at = NOW()
          WHERE id = item_rec.variant_id;
        ELSIF item_rec.kit_id IS NOT NULL THEN
          FOR comp_rec IN (SELECT * FROM public.kit_items WHERE kit_id = item_rec.kit_id) LOOP
            IF comp_rec.variant_id IS NOT NULL OR comp_rec.product_variant_id IS NOT NULL THEN
              UPDATE public.product_variants
              SET inventory_quantity = inventory_quantity + (comp_rec.quantity * item_rec.quantity),
                  updated_at = NOW()
              WHERE id = COALESCE(comp_rec.variant_id, comp_rec.product_variant_id);
            END IF;
          END LOOP;
        END IF;
      END LOOP;
    END IF;
    v_new_order_status := 'CANCELLED';
  END IF;

  UPDATE public.orders
  SET payment_status = p_payment_status,
      order_status = v_new_order_status,
      admin_note = COALESCE(p_notes, admin_note),
      notes = COALESCE(p_notes, notes),
      updated_at = NOW()
  WHERE id = p_order_id;

  INSERT INTO public.order_events (
    id, order_id, actor_type, actor_id, event_type, old_status, new_status, metadata, created_at
  ) VALUES (
    gen_random_uuid(), p_order_id, p_actor_type, p_actor_id, 'PAYMENT_STATUS_UPDATED',
    v_old_payment_status, p_payment_status,
    jsonb_build_object('order_status', v_new_order_status, 'notes', p_notes),
    NOW()
  );

  RETURN jsonb_build_object(
    'order_id', p_order_id,
    'payment_status', p_payment_status,
    'order_status', v_new_order_status
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$function$
